def conferir_schema_d60(conexao):
    nomes={n for (n,) in conexao.execute("SELECT name FROM sqlite_master WHERE type='table'")}
    presentes=nomes & set(DDL_D60)
    if not presentes:return False
    if presentes!=set(DDL_D60):raise RuntimeError('Estrutura D60 parcial; banco preservado.')
    normal=lambda s:''.join(s.split()).lower()
    for nome,ddl in {**DDL_D60,**INDICES_D60}.items():
        row=conexao.execute('SELECT sql FROM sqlite_master WHERE name=?',(nome,)).fetchone()
        if not row or not row[0] or normal(row[0])!=normal(ddl):raise RuntimeError('Estrutura D60 divergente; preservado: '+nome)
    cfg=conexao.execute('SELECT id,revision,ativada_em,segredo_verificacao FROM configuracao_preco_d60').fetchall()
    if cfg:
        if len(cfg)!=1 or cfg[0][0]!=1 or cfg[0][1]!=REVISION_D60:raise RuntimeError('Ativação D60 divergente; banco preservado.')
        try:
            data=datetime.fromisoformat(cfg[0][2].replace('Z','+00:00'))
            if data.tzinfo is None or len(bytes.fromhex(cfg[0][3]))!=32:raise ValueError()
        except (ValueError,TypeError):raise RuntimeError('Configuração D60 inválida; banco preservado.') from None
    elif any(conexao.execute('SELECT count(*) FROM '+identidade_sql(n)).fetchone()[0] for n in ('formacoes_preco_cotacao','eventos_formacao_preco')):
        raise RuntimeError('Preços D60 sem ativação correspondente; registros preservados.')
    return True

